signed main () 
{
    ios_base::sync_with_stdio(0); 
    cin.tie(0);cout.tie(0); 
    cin >> n >> k ; 
    map <int,int> mp ; 
    int First = -1 , Second = -1 ; 
    for ( int i = 1 ; i <= n ; i ++ )
    {
        cin >> a [i] ; 
        if ( mp [k-a[i]] ) First = mp [k-a[i]] , Second = i; 
        mp [a[i]] = i ; 
    } 
    if ( First == -1 ) cout << "IMPOSSIBLE" ; 
    else cout << First << " " << Second ; 
    return 0; 
}
